(6415606, 949741, 31637, '<td valign="top">Pretty scene, congratulations!</td>', 'Pretty scene, congratulations!', '2011-05-17 03:45:54.000000', NULL, 0),
(6415721, 949164, 123833, '<td valign="top">I had no idea that applying an automatic lens CORRECTION profile in LR is not allowed in Basic. I mentioned this correction in my comments so that must have caused a DQ check in the first place. (I should stop putting comments on my images!)<br/> <br/>Looking at it again automatic lens correction did not do a great job. The buildings are still leaning. I wonder if a wide angle lens that does not cause distortion like this actually exists?? <br/> <br/>Does it mean that wide angle lenses are not allowed in Basic? (at least on building shots where the problem is clearly visible) That''s an unusual restriction.<br/><br/><i>Message edited by author 2011-05-17 15:51:41.</i></td>', 'I had no idea that applying an automatic lens CORRECTION profile in LR is not allowed in Basic. I mentioned this correction in my comments so that must have caused a DQ check in the first place. (I should stop putting comments on my images!) Looking at it again automatic lens correction did not do a great job. The buildings are still leaning. I wonder if a wide angle lens that does not cause distortion like this actually exists??  Does it mean that wide angle lenses are not allowed in Basic? (at least on building shots where the problem is clearly visible) That''s an unusual restriction.', '2011-05-17 10:28:51.000000', '2011-05-17 16:51:41.000000', 0),
(6416535, 949264, 67258, '<td valign="top">I didn''t realise this was yours - huge congrats on our first ribbon, and straight to the top with a blue, at that.  Looking forward to seeing you on the front page again!  Apart from the light and the wonderful tones, especially on the bottom couple of sand ripples, is the inclusion of the two walkers, tight up against the top right edge - works superbly.<br/><br/><i>Message edited by author 2011-05-18 01:44:38.</i></td>', 'I didn''t realise this was yours - huge congrats on our first ribbon, and straight to the top with a blue, at that.  Looking forward to seeing you on the front page again!  Apart from the light and the wonderful tones, especially on the bottom couple of sand ripples, is the inclusion of the two walkers, tight up against the top right edge - works superbly.', '2011-05-18 02:43:01.000000', '2011-05-18 02:44:38.000000', 0),
(6419284, 949264, 131018, '<td valign="top">Beautiful shot</td>', 'Beautiful shot', '2011-05-20 07:48:40.000000', NULL, 0),
